pattern(/^(\d+)-year average \((\d{4})–(\d{4})\)$/,(_,n,a,b)=>'Średnia '+n+'-letnia ('+a+'–'+b+')');
pattern(/^(\d{4}) monthly average$/,(_,y)=>y+' — średnia miesięczna');
pattern(/^(\d{4}) average$/,(_,y)=>y+' — średnia');
pattern(/^(\d{4}) observations$/,(_,y)=>y+' — obserwacje');
pattern(/^Hollow marker: partial month, through (\d{4}-\d{2}-\d{2})\.$/,(_,d)=>'Pusty znacznik: niepełny miesiąc, do '+d+'.');
pattern(/^(\d+)-year normalization bases$/,(_,n)=>'Podstawy normalizacji '+n+'-letniej');
pattern(/^Colors compare unrounded monthly means with the last available daily observation through the cutoff, in the selected display units\. Matrix prices and the reference use ([0-3]) decimal places; calculations and colors retain full precision\. \* Current calendar month is partial\. — No data or month after cutoff \(hover for the reason\); counts appear on hover\. Colors describe historical price levels, not buy\/sell signals\.$/,(_,n)=>'Kolory porównują niezaokrąglone średnie miesięczne z ostatnią dostępną obserwacją dzienną do daty granicznej, w wybranych jednostkach prezentacji. Ceny w macierzy i punkt odniesienia mają '+n+' miejsc po przecinku; obliczenia i kolory zachowują pełną precyzję. * Bieżący miesiąc kalendarzowy jest niepełny. — Brak danych lub miesiąc po dacie granicznej (najedź, aby sprawdzić przyczynę); liczebności pojawiają się po najechaniu. Kolory opisują historyczne poziomy cen, nie sygnały kupna lub sprzedaży.');
pattern(/^Analysis cutoff: (\d{4}-\d{2}-\d{2})$/,(_,d)=>'Data graniczna analizy: '+d);
pattern(/^(\d+) days$/,(_,n)=>n+' dni');
pattern(/^Future observations excluded: (\d+)$/,(_,n)=>'Wykluczone przyszłe obserwacje: '+n);
pattern(/^ · Source: $/,()=> ' · Źródło: ');
pattern(/^Quote date (\d{4}-\d{2}-\d{2})$/,(_,d)=>'Data notowania '+d);
pattern(/^Published (\d{4}-\d{2}-\d{2})$/,(_,d)=>'Opublikowano '+d);
pattern(/^Historical (\d+)% VaR$/,(_,n)=>'Historyczny VaR '+n+'%');
pattern(/^(buyer|seller) adverse-change perspective$/,(_,s)=>(s==='buyer'?'Perspektywa kupującego':'Perspektywa sprzedającego')+' — niekorzystna zmiana');
pattern(/^Amount in ([A-Z]{3})$/,(_,u)=>'Kwota w '+u);
pattern(/^Import column ([A-Z]{1,3})$/,(_,c)=>'Importuj kolumnę '+c);
pattern(/^Title for column ([A-Z]{1,3})$/,(_,c)=>'Nazwa dla kolumny '+c);
pattern(/^Units for column ([A-Z]{1,3})$/,(_,c)=>'Jednostki dla kolumny '+c);
pattern(/^Role for column ([A-Z]{1,3})$/,(_,c)=>'Rola dla kolumny '+c);
pattern(/^(\d+) CSV data rows · first 10 physical row starts shown\. The first row is the header\.$/,(_,n)=>n+' wierszy danych CSV · pokazano początki pierwszych 10 fizycznych wierszy. Pierwszy wiersz jest nagłówkiem.');
pattern(/^Added (\d+) instrument\(s\) privately in this tab\. Reloading clears these imports\. See each instrument’s last observation date above\.$/,(_,n)=>'Dodano '+n+' instrumentów prywatnie w tej karcie. Odświeżenie usuwa te importy. Ostatnia data obserwacji każdego instrumentu jest widoczna powyżej.');
pattern(/^(\d+) instrument\(s\) validated through (\d{4}-\d{2}-\d{2})\. (?:(\d+) empty trailing worksheet row\(s\) ignored\. )?(?:(\d+) cached formula result\(s\) accepted explicitly; these may be stale\. )?Nothing has been added yet\.$/,(_,n,d,empty,cached)=>n+' instrumentów sprawdzonych do '+d+'. '+(empty?empty+' pustych końcowych wierszy arkusza pominięto. ':'')+(cached?cached+' zapisanych wyników formuł zaakceptowano jawnie; mogą być nieaktualne. ':'')+'Nie dodano jeszcze żadnych danych.');
