 const doc=root.document;if(doc){for(const lang of ['en','pl'])doc.getElementById('language-'+lang)?.addEventListener('click',()=>setLanguage(lang));translateTree(doc.body);syncControls();if(typeof root.MutationObserver==='function'){observer=new root.MutationObserver(recordsChanged);observe();}}
